function loadRobotArmor(){const src=window.VECTOR_SKIN_DATA||new URL('./assets/robot-armor.png',location.href).href;armorTexture=new THREE.TextureLoader().load(src,texture=>{texture.colorSpace=THREE.SRGBColorSpace;texture.wrapS=texture.wrapT=THREE.RepeatWrapping;texture.repeat.set(1,1);worldGroup?.traverse(o=>{if(!o.isMesh)return;const materials=Array.isArray(o.material)?o.material:[o.material];for(const m of materials)if(m?.userData.agentOwned&&m.userData.useArmorTexture){m.map=texture;m.needsUpdate=true}})});}
function makeAgent(color=0x909e84,enemy=false,skinId=null){const skin=skinId===null?null:agentSkins[normalizeSkinId(skinId)];color=skin?.outfit??color;const g=new THREE.Group(),dark=skin?.pants??(enemy?0x303b38:0x2a3430),accent=skin?.accent??(enemy?0xfca562:0xd3f878);const hips=box(g,0,.92,0,.57,.3,.38,dark);const torso=box(g,0,1.35,0,.76,.62,.42,color,{metal:.35});box(g,0,1.39,.23,.48,.38,.12,dark);box(g,0,1.48,.301,.32,.04,.025,accent,{emissive:accent});box(g,0,1.18,.29,.35,.11,.06,color);for(const x of [-.17,0,.17])box(g,x,1.02,.245,.12,.18,.1,dark);cylinder(g,0,1.76,0,.12,.14,.15,dark);const head=box(g,0,1.97,0,.46,.43,.44,skin?.face??color,{metal:skin?.id===9?.5:.12});if(!skin){box(g,0,1.99,.232,.38,.14,.025,0x1a2925,{emissive:enemy?0xfc5842:0xc5f59a});box(g,0,2.17,-.02,.32,.08,.33,dark);box(g,-.25,1.97,0,.08,.21,.3,dark);box(g,.25,1.97,0,.08,.21,.3,dark);box(g,0,1.85,.245,.18,.1,.05,dark)}const legs=[];for(const s of [-1,1]){const pivot=new THREE.Group();pivot.position.set(s*.2,.9,0);g.add(pivot);box(pivot,0,-.23,0,.25,.44,.28,dark);box(pivot,0,-.27,.13,.25,.28,.1,color);const knee=new THREE.Group();knee.position.set(0,-.48,0);pivot.add(knee);box(knee,0,-.04,.06,.27,.17,.3,color);box(knee,0,-.22,0,.23,.3,.25,dark);const foot=new THREE.Group();foot.position.set(0,-.34,.13);knee.add(foot);box(foot,0,0,0,.3,.16,.5,dark);pivot.userData.knee=knee;pivot.userData.foot=foot;legs.push(pivot)}const arms=[];for(const s of [-1,1]){const a=new THREE.Group();a.position.set(s*.48,1.57,0);g.add(a);box(a,0,-.07,0,.27,.25,.35,color);box(a,0,-.32,.1,.2,.35,.25,dark);box(a,-s*.11,-.5,.29,.2,.22,.48,color);box(a,-s*.11,-.48,.53,.18,.18,.17,dark);arms.push(a)}const gun=new THREE.Group();gun.position.set(.07,1.22,.79);g.add(gun);box(gun,-.07,-.12,-.24,.18,.22,.65,dark,{metal:.7});box(gun,0,0,0,.18,.15,.86,dark,{metal:.6});const bar=cylinder(gun,0,0,.56,.04,.04,.4,0x65715c);bar.rotation.x=Math.PI/2;box(gun,-.01,.16,-.14,.12,.15,.21,0x1d2923);box(g,0,1.36,-.3,.5,.48,.23,dark);
 if(skin)dressAgent(THREE,g,skin,{box});
 const skeleton=articulateAgent(THREE,g,{hips,torso,head,legs,arms,gun});
 const owned=new Map(),hitMaterials=[];g.traverse(o=>{if(!o.isMesh)return;const original=o.material;if(!owned.has(original)){const material=original.clone();material.userData.agentOwned=true;material.userData.useArmorTexture=!skin;if(!skin&&armorTexture)material.map=armorTexture;owned.set(original,material);hitMaterials.push({material,color:material.color.clone(),emissive:material.emissive.clone(),intensity:material.emissiveIntensity})}o.material=owned.get(original)});
 const flash=new THREE.Mesh(new THREE.ConeGeometry(.13,.34,5),new THREE.MeshBasicMaterial({color:0xffd27e,transparent:true,opacity:.95,depthWrite:false}));flash.material.userData.agentOwned=true;flash.rotation.x=Math.PI/2;flash.position.z=.89;flash.visible=false;gun.add(flash);
 g.userData={skinId:skin?.id??null,skeleton,hips,legs,arms,head,torso,gun,flash,hitMaterials,hitTime:0,shootTime:0,hitColor:new THREE.Color(0xff173d),hitEmissive:new THREE.Color(0xa50915)};return g}
function flashAgent(mesh){if(mesh?.userData.hitMaterials){mesh.userData.hitTime=.22;animateAgent(mesh,0)}}
function fireAgent(mesh){if(mesh?.userData.gun){mesh.userData.shootTime=.18;animateAgent(mesh,0)}}
function animateAgent(mesh,dt,pitch=0){
 const d=mesh.userData;if(!d.hitMaterials)return;d.hitTime=Math.max(0,d.hitTime-dt);d.shootTime=Math.max(0,d.shootTime-dt);
 const flash=d.hitTime>0?Math.min(1,d.hitTime/.06):0;for(const m of d.hitMaterials){m.material.color.copy(m.color).lerp(d.hitColor,flash*.9);m.material.emissive.copy(m.emissive).lerp(d.hitEmissive,flash);m.material.emissiveIntensity=flash?1:m.intensity}
 if(!d.gun)return;
 if(!d.restPose)d.restPose={gun:restTransform(d.gun),head:restTransform(d.head),torso:restTransform(d.torso),arms:d.arms.map(restTransform),legs:d.legs.map(leg=>({...restTransform(leg),r:[0,0,0]}))};
 const p=agentActionPose({...d.poseState,pitch,shootTime:d.shootTime,hitTime:d.hitTime});d.gun.visible=!p.emoting;if(p.emoting)mesh.rotation.y=(d.poseState?.baseYaw??mesh.rotation.y)+(p.rootYaw||0);applyModelPose(d.gun,d.restPose.gun,p.gunPosition,p.gunRotation);applyModelPose(d.head,d.restPose.head);applyModelPose(d.torso,d.restPose.torso);d.arms.forEach((arm,i)=>applyModelPose(arm,d.restPose.arms[i],p.arms[i].position,p.arms[i].rotation));
 if(d.poseState)d.legs.forEach((leg,i)=>{applyModelPose(leg,d.restPose.legs[i],[0,0,0],p.legs[i].rotation);if(leg.userData.knee)leg.userData.knee.rotation.x=p.legs[i].knee;if(leg.userData.foot)leg.userData.foot.rotation.x=p.legs[i].foot});
 poseAgentRig(THREE,mesh,p);
 d.flash.visible=d.shootTime>.12;d.flash.scale.setScalar(.8+p.shoot*.4);
}

function retireAgent(mesh){flashAgent(mesh);dyingAgents.push({mesh,life:.18})}
function updateDyingAgents(dt){for(let i=dyingAgents.length-1;i>=0;i--){const d=dyingAgents[i];d.life-=dt;if(d.life<=0){worldGroup.remove(d.mesh);d.mesh.traverse(o=>{o.geometry?.dispose();if(o.material?.map&&o.material.map!==armorTexture)o.material.map.dispose();if(o.material?.map||o.material?.userData.agentOwned)o.material.dispose()});dyingAgents.splice(i,1)}else{animateAgent(d.mesh,dt);d.mesh.scale.y=Math.max(.75,d.life/.18);for(const m of d.mesh.userData.hitMaterials){m.material.transparent=true;m.material.opacity=d.life/.18}}}}

function clearWorld(){abilityBlocks.clear();clearBotShots();localAvatar=null;dyingAgents.length=0;for(const id of projectileVisuals.keys())removeProjectileVisual(id);localProjectiles.length=0;remoteAgents.clear();if(worldGroup){const geos=new Set();worldGroup.traverse(o=>{if(o.geometry)geos.add(o.geometry);if(o.material?.map){if(o.material.map!==armorTexture)o.material.map.dispose();o.material.dispose()}else if(o.material?.userData.agentOwned||o.material?.userData.mapArtOwned)o.material.dispose()});geos.forEach(g=>g.dispose());scene.remove(worldGroup)}cover=[];coverMeshes=[];enemies=[];effects.forEach(e=>{scene.remove(e.mesh);e.mesh.geometry?.dispose();e.mesh.material?.dispose()});effects=[];decor=[];worldGroup=new THREE.Group();scene.add(worldGroup)}
