function createWeapon(notify=true){if(!previewMode){weaponEpoch++;burstRemaining=0;shotBuffer.clear();}if(rigWeapon!==null){magazineInventory.set(rigWeapon,ammo);reserveInventory.set(rigWeapon,reserveAmmo)}if(!previewMode)cancelDraw();if(weaponRig){viewScene.remove(weaponRig);weaponRig.traverse(o=>{o.geometry?.dispose();if(o.material?.transparent||o.isLine)o.material?.dispose()})}const w=weapons[selectedWeapon],pistol=w.cat==='hg',sniper=w.cat==='sr',sg=w.cat==='sg',smg=w.cat==='smg',lmg=w.cat==='lmg';weaponRig=new THREE.Group();weaponRig.scale.setScalar(.7);viewScene.add(weaponRig);const metal=0x29332e,body=w.color,accent=0xd3f878;if(w.mechanic||w.fantasy){createSpecialWeapon(w);finishWeapon(w,notify);return}const length=(pistol?.47:sniper?1.18:sg?1.02:smg?.64:.88)*( .96+(w.id%4)*.025);box(weaponRig,0,0,0,pistol?.14:.19,pistol?.16:.22,length,body,{metal:.65,rough:.38});box(weaponRig,0,.12,-length*.1,.14,.055,length*.73,metal,{metal:.7});for(let i=0;i<9;i++)box(weaponRig,0,.16,-length*.4+i*length*.065,.16,.035,.025,metal,{metal:.7});box(weaponRig,0,-.18,length*.27,.13,.3,.16,metal,{metal:.5});const mag=box(weaponRig,0,-.26,pistol?length*.2:-length*.07,lmg?.3:.12,lmg?.24:.31,lmg?.26:.2,metal,{metal:.5});mag.rotation.x=pistol?0:-.15;if(!pistol){box(weaponRig,0,.005,length*.68,.16,.2,.45,metal,{metal:.4});box(weaponRig,0,-.025,length*.92,.2,.29,.07,body);box(weaponRig,0,0,-length*.39,.23,.2,length*.4,metal);for(let i=0;i<5;i++){box(weaponRig,-.119,.015,-length*.5+i*.07,.012,.1,.03,body);box(weaponRig,.119,.015,-length*.5+i*.07,.012,.1,.03,body)}}const barrel=cylinder(weaponRig,0,.02,-length*.72,.035,.035,length*.4,0x3b4740,12);barrel.rotation.x=Math.PI/2;const tip=sniper?-1.405:-length*.92;const muzzlePart=cylinder(weaponRig,0,.02,tip,.05,.05,.09,metal);muzzlePart.rotation.x=Math.PI/2;box(weaponRig,.105,.015,.17,.011,.08,.12,accent);box(weaponRig,-.105,.025,.12,.011,.04,.1,0x7f8c73);const glove=0x303e32,sleeve=0x657456;const right=box(weaponRig,.07,-.25,.29,.18,.23,.24,glove);right.rotation.x=-.2;const forearm=box(weaponRig,.16,-.42,.49,.22,.23,.57,sleeve);forearm.rotation.x=-.25;forearm.visible=false;const left=box(weaponRig,-.13,-.16,-.3,.18,.2,.28,glove);left.rotation.z=-.15;const lf=box(weaponRig,-.3,-.32,-.02,.22,.22,.65,sleeve);lf.rotation.y=-.5;lf.visible=false;const bolt=box(weaponRig,.104,.045,.06,.018,.065,.16,0x778877,{metal:.8});weaponParts={mag,bolt,supportHand:left,triggerHand:right};muzzle=new THREE.Mesh(new THREE.ConeGeometry(.14,.35,7),new THREE.MeshBasicMaterial({color:0xffe2a0,transparent:true,opacity:.85}));muzzle.rotation.x=-Math.PI/2;muzzle.position.set(0,.02,tip-.18);muzzle.visible=false;weaponRig.add(muzzle);muzzleLight=new THREE.PointLight(0xffd98b,0,3);muzzleLight.position.set(0,.05,tip);weaponRig.add(muzzleLight);addWeaponDetails(THREE,weaponRig,w);finishWeapon(w,notify)}
function restTransform(node){return {p:node.position.toArray(),r:[node.rotation.x,node.rotation.y,node.rotation.z]}}
function applyModelPose(node,base,position=[0,0,0],rotation=[0,0,0]){if(!node||!base)return;node.position.set(base.p[0]+position[0],base.p[1]+position[1],base.p[2]+position[2]);node.rotation.set(base.r[0]+rotation[0],base.r[1]+rotation[1],base.r[2]+rotation[2])}
function finishWeapon(w,notify=true){addViewArms(THREE,weaponRig,weaponParts,mat(agentSkins[selectedSkin].outfit));weaponParts.rest={};for(const[key,part]of Object.entries(weaponParts))if(part?.isObject3D)weaponParts.rest[key]=restTransform(part);if(previewMode)return;aim=false;rigWeapon=selectedWeapon;ammo=magazineInventory.get(selectedWeapon)??w.mag;reserveAmmo=reserveInventory.get(selectedWeapon)??w.reserve;reloading=0;pendingReload=0;weaponSwitch=.4;shotCooldown=Math.max(shotCooldown,.25);updateWeaponHud();renderQuickSlots();if(combat&&mode==='online'&&notify){pendingOnlineShots=[];pendingEquip=++actionSeq;net.send({type:'equip',weapon:selectedWeapon,seq:pendingEquip})}else pendingEquip=0}
function applyServerLoadout(packet,serverTime){
 if(packet.weapon!==selectedWeapon)return;
 const oldAmmo=ammo,oldReserve=reserveAmmo,wasReloading=reloading>0,w=weapons[selectedWeapon];
 ammo=w.mechanic==='melee'?1:Math.min(w.mag,Math.max(0,packet.ammo-pendingOnlineShots.length));
 if(Number.isFinite(packet.reserve))reserveAmmo=Math.max(0,Math.min(w.reserve,packet.reserve));
 reserveInventory.set(selectedWeapon,reserveAmmo);
 reloading=packet.health===0?0:Math.max(0,((packet.reloadAt||0)-serverTime)/1000);
 magazineInventory.set(selectedWeapon,ammo);
 if(wasReloading&&reloading===0&&ammo>oldAmmo&&!paused)sound('reload');
 if(oldAmmo!==ammo||oldReserve!==reserveAmmo||wasReloading!==(reloading>0)){updateWeaponHud();$('reloadHint').innerHTML=reloading>0?'재장전 중…':'R 재장전 <b>·</b> 1~3 무기 전환 <b>·</b> B 무기고'}
}
function syncInventoryFromSnapshot(self,serverTime){if(pendingEquip||pendingReload||self.weapon!==selectedWeapon)return;applyServerLoadout(self,serverTime)}
function handleEquipAck(m){
 if(!combat||mode!=='online'||!pendingEquip||m.seq!==pendingEquip)return;
 pendingEquip=0;
 if(Number.isInteger(m.weapon)&&weapons[m.weapon]&&m.weapon!==selectedWeapon){pendingReload=0;pendingOnlineShots=[];selectedWeapon=m.weapon;inspectedWeapon=m.weapon;storage.set('weapon',selectedWeapon);createWeapon(false)}
 if(!pendingReload)applyServerLoadout(m,m.serverTime??net.serverNow);
}
function handleReloadAck(m){
 if(!combat||mode!=='online'||!pendingReload||m.seq!==pendingReload)return;
 pendingReload=0;if(!pendingEquip&&m.weapon===selectedWeapon)applyServerLoadout(m,m.serverTime??net.serverNow);
}
function handleShotAck(m){
 if(!combat||mode!=='online'||m.weapon!==selectedWeapon)return;
 pendingOnlineShots=pendingOnlineShots.filter(n=>n>m.seq);
 if(!pendingEquip&&!pendingReload)applyServerLoadout(m,m.serverTime??net.serverNow);
}
